import React, { useState } from 'react';
import './App.css';

export default function App() {
  // 0 = basic, 1 = address, 2 = summary
  const [currentStep, setCurrentStep] = useState(0);

  // Top-level form state (controlled inputs)
  const [form, setForm] = useState({
    basic: { name: '', email: '' },
    address: { street: '', city: '', country: '', postalCode: '' }
  });

  const [showErrors, setShowErrors] = useState(false);
  const [submitMessage, setSubmitMessage] = useState('');

  // Derived validation for each step
  const basicErrors = {
    name: form.basic.name.trim().length === 0,
    email: form.basic.email.trim().length === 0
  };
  const isBasicValid = !basicErrors.name && !basicErrors.email;

  const addressErrors = {
    street: form.address.street.trim().length === 0,
    city: form.address.city.trim().length === 0,
    country: form.address.country.trim().length === 0
  };
  const isAddressValid = !addressErrors.street && !addressErrors.city && !addressErrors.country;

  const isFirstStep = currentStep === 0;
  const isLastStep = currentStep === 2;

  const canGoNext =
    currentStep === 0 ? isBasicValid :
    currentStep === 1 ? isAddressValid :
    false;

  const canSubmit = isBasicValid && isAddressValid;

  function updateBasic(key: 'name' | 'email', value: string) {
    setForm(prev => ({
      ...prev,
      basic: { ...prev.basic, [key]: value }
    }));
  }

  function updateAddress(key: 'street' | 'city' | 'country' | 'postalCode', value: string) {
    setForm(prev => ({
      ...prev,
      address: { ...prev.address, [key]: value }
    }));
  }

  function next() {
    setSubmitMessage('');
    if (!canGoNext) {
      setShowErrors(true);
      return;
    }
    setShowErrors(false);
    setCurrentStep(step => (step < 2 ? step + 1 : step));
  }

  function prev() {
    setSubmitMessage('');
    if (isFirstStep) return;
    setShowErrors(false);
    setCurrentStep(step => (step > 0 ? step - 1 : step));
  }

  function submit() {
    setSubmitMessage('');
    const valid = isBasicValid && isAddressValid;
    if (!valid) {
      setShowErrors(true);
      if (!isBasicValid) {
        setCurrentStep(0);
      } else if (!isAddressValid) {
        setCurrentStep(1);
      }
      return;
    }

    console.log('submit() called with value:', form);
    setSubmitMessage('Signup submitted! Check the console for payload.');
  }

  const { basic, address } = form;

  return (
    <main className="app">
      <section className="card">
        <header className="header">
          <h1>Multi-step Signup</h1>
          <p className="subtitle">Step {currentStep + 1} of 3</p>
        </header>

        <section className="steps">
          {currentStep === 0 && (
            <div className="step">
              <h2 className="step-title">Basic info</h2>

              <label className="field">
                <span>Name</span>
                <input
                  type="text"
                  placeholder="Jane Doe"
                  value={basic.name}
                  onChange={e => updateBasic('name', e.target.value)}
                />
                {showErrors && basicErrors.name && (
                  <small className="error">Name is required.</small>
                )}
              </label>

              <label className="field">
                <span>Email</span>
                <input
                  type="email"
                  placeholder="jane@example.com"
                  value={basic.email}
                  onChange={e => updateBasic('email', e.target.value)}
                />
                {showErrors && basicErrors.email && (
                  <small className="error">Please enter a valid email.</small>
                )}
              </label>
            </div>
          )}

          {currentStep === 1 && (
            <div className="step">
              <h2 className="step-title">Address</h2>

              <label className="field">
                <span>Street</span>
                <input
                  type="text"
                  placeholder="123 Main St"
                  value={address.street}
                  onChange={e => updateAddress('street', e.target.value)}
                />
                {showErrors && addressErrors.street && (
                  <small className="error">Street is required.</small>
                )}
              </label>

              <label className="field">
                <span>City</span>
                <input
                  type="text"
                  placeholder="Istanbul"
                  value={address.city}
                  onChange={e => updateAddress('city', e.target.value)}
                />
                {showErrors && addressErrors.city && (
                  <small className="error">City is required.</small>
                )}
              </label>

              <label className="field">
                <span>Country</span>
                <input
                  type="text"
                  placeholder="Türkiye"
                  value={address.country}
                  onChange={e => updateAddress('country', e.target.value)}
                />
                {showErrors && addressErrors.country && (
                  <small className="error">Country is required.</small>
                )}
              </label>

              <label className="field">
                <span>Postal code (optional)</span>
                <input
                  type="text"
                  placeholder="34000"
                  value={address.postalCode}
                  onChange={e => updateAddress('postalCode', e.target.value)}
                />
              </label>
            </div>
          )}

          {currentStep === 2 && (
            <div className="step">
              <h2 className="step-title">Summary</h2>
              <div className="summary">
                <h3>Basic info</h3>
                <p><strong>Name:</strong> {basic.name || '—'}</p>
                <p><strong>Email:</strong> {basic.email || '—'}</p>

                <h3>Address</h3>
                <p><strong>Street:</strong> {address.street || '—'}</p>
                <p><strong>City:</strong> {address.city || '—'}</p>
                <p><strong>Country:</strong> {address.country || '—'}</p>
                <p><strong>Postal code:</strong> {address.postalCode || '—'}</p>
              </div>
            </div>
          )}
        </section>

        <footer className="actions">
          <button
            type="button"
            className="ghost"
            onClick={prev}
            disabled={isFirstStep}
          >
            Back
          </button>

          {!isLastStep && (
            <button
              type="button"
              onClick={next}
              disabled={!canGoNext}
            >
              Next
            </button>
          )}

          {isLastStep && (
            <button
              type="button"
              className="primary"
              onClick={submit}
              disabled={!canSubmit}
            >
              Submit
            </button>
          )}
        </footer>
        {submitMessage && (
          <p className="success" role="status">{submitMessage}</p>
        )}
      </section>
    </main>
  );
}

