:root {
  color-scheme: dark;
}

html, body {
  margin: 0;
  height: 100%;
  background: #020617;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.app {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #020617;
  color: #e5e7eb;
  padding: 24px;
}

.card {
  width: 100%;
  max-width: 520px;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 20px 20px 16px;
  display: grid;
  gap: 16px;
}

.header h1 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
}

.subtitle {
  margin: 4px 0 0;
  font-size: 13px;
  color: #9ca3af;
}

.steps {
  min-height: 260px;
}

.step {
  display: grid;
  gap: 12px;
}

.step-title {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 600;
}

.field {
  display: grid;
  gap: 4px;
  font-size: 13px;
}

.field span {
  color: #e5e7eb;
}

.field input {
  border-radius: 10px;
  border: 1px solid #374151;
  background: #020617;
  padding: 8px 10px;
  color: #e5e7eb;
  font-size: 14px;
}

.field input:focus {
  outline: none;
  border-color: #a3e635;
}

.error {
  font-size: 11px;
  color: #f97316;
}

.summary {
  display: grid;
  gap: 4px;
  font-size: 14px;
}

.summary h3 {
  margin: 8px 0 2px;
  font-size: 14px;
  font-weight: 600;
  color: #e5e7eb;
}

.actions {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 4px;
}

.actions button {
  border-radius: 999px;
  border: 1px solid #374151;
  background: #020617;
  color: #e5e7eb;
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.actions button.primary {
  background: #a3e635;
  color: #020617;
  border-color: #a3e635;
}

.actions button[disabled] {
  opacity: .5;
  cursor: not-allowed;
}

.actions button.ghost {
  background: transparent;
}

.success {
  margin: -4px 0 0;
  font-size: 13px;
  color: #a3e635;
  font-weight: 700;
}
